user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "PLANS_END_TO_END_VERIFICATION",
    "definition": "The reasoning specifies a verification procedure that reproduces the requester's own end-user workflow against the configured system and states the expected observable result of the procedure.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that lays out the forthcoming validation procedure and its expected outcome."
      }
    ],
    "assertion_conditions": [
      "The reasoning names at least one end-user interaction described in the request (login, clone, commit, push, fetch of the deployed path) as something to be executed for validation.",
      "The reasoning states what result that procedure should produce, so that success can be judged."
    ],
    "exclusion_conditions": [
      "The reasoning only describes configuration changes to be made.",
      "The reasoning only reports results of checks already completed without specifying a forthcoming validation procedure."
    ]
  },
  {
    "name": "EXECUTES_USER_WORKFLOW_TRIAL",
    "definition": "The action runs the requester's prescribed command sequence, or a faithful stand-in for it, against the configured system as a functional trial of the delivered capability rather than as configuration or state inspection.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that exercises the user-facing flow end to end."
      }
    ],
    "assertion_conditions": [
      "The invocation contains commands reproducing the end-user interaction from the request, such as a remote clone followed by commit and push, or an HTTP fetch of the deployed path.",
      "The invocation is performed after the system has been configured, so that its result reflects the delivered capability."
    ],
    "exclusion_conditions": [
      "The invocation only edits configuration files, starts services, or inspects filesystem/process state.",
      "The invocation exercises only an internal component rather than the requester-visible flow."
    ]
  },
  {
    "name": "OBSERVATION_CONFIRMS_REQUESTED_BEHAVIOR",
    "definition": "The observation result matches the end-user-visible behavior stated in the request, giving direct evidence that the delivered system produces the requested outcome.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result carrying the outcome of the user-facing interaction."
      }
    ],
    "assertion_conditions": [
      "The output contains the exact result the requester said they expect, such as served content equal to the specified payload, and is returned without an error status."
    ],
    "exclusion_conditions": [
      "The output shows only configuration, process, or filesystem state.",
      "The output differs from the requested result, is empty, or reports an HTTP error or missing resource."
    ]
  },
  {
    "name": "OBSERVATION_CONFIRMS_SERVICE_AVAILABILITY",
    "definition": "The observation provides evidence that the required long-running services are active and reachable, either through live process entries or through listening-socket entries for the required ports.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result listing running processes or listening sockets."
      }
    ],
    "assertion_conditions": [
      "The output shows running process instances for the required daemons, or sockets in the listening state for the required ports.",
      "The evidence is produced without error markers or missing entries for the required services."
    ],
    "exclusion_conditions": [
      "The output is only a configuration syntax validation.",
      "The output is only a confirmation that a file was written or edited.",
      "The output shows the service names but no indication that the processes are running or the ports are listening."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE_CAUSE",
    "definition": "The reasoning attributes an observed tool failure to a specific identifiable cause and explains why that cause produced this failure in the current execution context.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text offering the causal explanation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The earlier tool result reporting the failure being explained."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a concrete cause, such as an environment setting applied to only part of a command chain, an ownership restriction, or an interpreter capability limitation.",
      "The reasoning states the causal link between that cause and the specific error text in the observation."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates or quotes the error without attribution.",
      "The reasoning retries the step with no explanation of why it failed.",
      "The explanation concerns a different observation than the one reporting the failure."
    ]
  },
  {
    "name": "ATTRIBUTES_FAILURE_TO_TRIAL_SETUP",
    "definition": "The reasoning concludes that an observed failure originates in the agent's own trial setup or command construction rather than in the delivered system, so no change to the delivered configuration is required.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text classifying the origin of the failure."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result reporting the failure whose origin is being classified."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly links the failure to a characteristic of the trial environment or of how the trial command was assembled.",
      "The reasoning states that the delivered system itself remains correct or that the failure would not occur for the requester."
    ],
    "exclusion_conditions": [
      "The reasoning treats the failure as a defect of the delivered system.",
      "The reasoning does not distinguish trial-induced failure from genuine system failure."
    ]
  },
  {
    "name": "JUDGES_OBSERVATION_CONCLUSIVENESS",
    "definition": "The reasoning evaluates whether a low-detail or empty observation is sufficient to establish the intended property, using auxiliary cues such as reported size, expected file content, or known tool limitations.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text assessing the evidential value of the observation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The low-detail, empty, or indirect tool result being assessed."
      }
    ],
    "assertion_conditions": [
      "The reasoning explains why the observation's content, or its absence of output, does or does not establish the target property.",
      "When the evidence is judged insufficient, the reasoning states what alternative evidence would be required."
    ],
    "exclusion_conditions": [
      "The reasoning accepts the observation's output at face value without evaluating its sufficiency.",
      "The reasoning addresses a different observation than the one being judged."
    ]
  },
  {
    "name": "ATTEMPTS_REPAIR",
    "definition": "The action re-executes a step that a prior observation reported as failing, with execution details changed so as to remove the cause identified for that failure.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The re-execution that targets the previously failing step."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The earlier tool result reporting the failure."
      }
    ],
    "assertion_conditions": [
      "The action targets the same step or operation that the earlier observation reported as failing.",
      "The action's arguments or environment differ from the failing attempt in a way that corresponds to the identified cause."
    ],
    "exclusion_conditions": [
      "The action retries the same step with unchanged execution details.",
      "The action addresses a different step or a different failure than the one observed.",
      "The change is unrelated to the cause of the reported failure."
    ]
  },
  {
    "name": "CONFIRMS_REPAIR",
    "definition": "A repair action addresses a previously observed failure and a subsequent result establishes that the same step now completes successfully.",
    "parameters": [
      {
        "name": "repair",
        "type": "action",
        "description": "The action attempting to repair the failure."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The earlier tool result reporting the failure."
      },
      {
        "name": "check_result",
        "type": "observation",
        "description": "The later tool result establishing that the failure is resolved."
      }
    ],
    "assertion_conditions": [
      "The failure precedes the repair and identifies the failing step.",
      "The repair targets that same step with modified execution details.",
      "A subsequent observation shows the step completing successfully and producing its expected effect."
    ],
    "exclusion_conditions": [
      "The repair is attempted without a result confirming success.",
      "The later result concerns a different step than the one that failed.",
      "The later result shows a new or different failure."
    ]
  },
  {
    "name": "DELEGATES_OPERATION_TO_RESOURCE_OWNER",
    "definition": "In response to a reported ownership or permission rejection, the action performs the operation under the identity that owns the resource instead of the rejected identity.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The invocation that re-executes the operation under the owning identity."
      },
      {
        "name": "rejection",
        "type": "observation",
        "description": "The earlier tool result reporting the ownership or permission error."
      }
    ],
    "assertion_conditions": [
      "The earlier observation contains an ownership or permission refusal that names the resource.",
      "The action switches the executing identity to the owning account while preserving the operation's target and intent."
    ],
    "exclusion_conditions": [
      "The earlier error concerns connectivity, availability, or a missing file rather than ownership or permission.",
      "The action resolves the refusal by changing the resource's ownership or permissions instead of changing the executing identity.",
      "The action continues to run under the rejected identity."
    ]
  },
  {
    "name": "CLEANS_TEST_ARTIFACTS",
    "definition": "The action removes or reverts data created during the agent's own trials — temporary credentials, cloned working copies, pushed references and objects, and files deployed by the trials — so the delivered system returns to its pre-test state.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The cleanup invocation removing trial-created state."
      }
    ],
    "assertion_conditions": [
      "The invocation deletes or resets entities the trials created, such as temporary keys, test clones, test commits or branch references, and files deployed by the trials.",
      "The invocation restores the initial structural state of the affected locations."
    ],
    "exclusion_conditions": [
      "The invocation only performs routine configuration or service management.",
      "The invocation deletes resources that belong to the delivered system rather than to the trials.",
      "The invocation only inspects state without modifying it."
    ]
  },
  {
    "name": "REVISES_INSPECTION_METHOD",
    "definition": "The action repeats an inspection with a different technique because a prior observation showed that the earlier technique could not yield a usable answer in this environment.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The invocation that inspects the same target using an alternative technique."
      },
      {
        "name": "inconclusive_result",
        "type": "observation",
        "description": "The earlier inspection result that produced no usable output or an environment-related error."
      }
    ],
    "assertion_conditions": [
      "The earlier inspection observation yields no usable output, or an error attributable to a tool or environment limitation.",
      "The new action inspects the same target with an alternative technique whose output does not depend on that limitation."
    ],
    "exclusion_conditions": [
      "The new action inspects a different target than the earlier inspection.",
      "The earlier observation already provided the required answer."
    ]
  },
  {
    "name": "PRESERVES_USER_COMMAND_PRECONDITIONS",
    "definition": "The reasoning identifies residual state that would cause the requester's own prescribed commands to fail and concludes that this state must be removed or reverted before handoff.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text linking leftover state to a concrete failure in the requester's command sequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific leftover artifact, such as an already-existing commit or an already-deployed file.",
      "The reasoning names the concrete command from the request that would fail or misbehave because of that artifact, and calls for reverting it."
    ],
    "exclusion_conditions": [
      "The reasoning argues only for general tidiness without naming a command that would fail.",
      "The reasoning concludes the leftover state is harmless for the requester's commands."
    ]
  },
  {
    "name": "JUSTIFIES_PREPARED_HANDOFF_STATE",
    "definition": "The reasoning justifies deliberately leaving a pre-created but empty or inert artifact in place because it eases the requester's own subsequent manual step, as opposed to deleting it or pre-populating it with functional data.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text weighing removal against retention of a prepared artifact."
      }
    ],
    "assertion_conditions": [
      "The reasoning compares removing the prepared artifact with keeping it in an empty or inert form.",
      "The reasoning concludes that keeping it lets the requester's own setup step succeed without extra work."
    ],
    "exclusion_conditions": [
      "The reasoning only plans removal of the artifact.",
      "The reasoning pre-populates functional data that the requester is supposed to supply themselves."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses an intended future action or sequence of actions that the agent intends to carry out next.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action or sequence of actions."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one action to be performed later, such as inspecting a file, writing content, compiling, or verifying output.",
      "The intended action is stated prospectively rather than reported as already done."
    ],
    "exclusion_conditions": [
      "The reasoning only reports or summarizes actions already completed.",
      "The reasoning only restates file content or tool output without expressing an intended next action."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_FAILURE",
    "definition": "The reasoning explains the cause of a failure reported by an observation and derives a corrective approach from that explanation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text explaining why the observed failure occurred and what should change."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The observation reporting the failure being explained."
      }
    ],
    "assertion_conditions": [
      "The observation indicates that an invoked operation did not succeed.",
      "The reasoning identifies a concrete cause for the failure and states a corrective approach or change based on that cause."
    ],
    "exclusion_conditions": [
      "The reasoning merely notes that something failed without offering a causal explanation.",
      "The reasoning explains an unrelated issue or offers no corrective direction."
    ]
  },
  {
    "name": "GUIDES_ACTION",
    "definition": "The action's tool choice, target, or argument values instantiate an intent, diagnosis, or corrected approach explicitly stated in the reasoning.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text stating the plan, diagnosis, or corrected approach."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The action whose tool, target, or arguments carry out that stated approach."
